__ht__function(json, dm, view, datas) {// ======================================================
// 🔥 加热炉炉内流（Heat Furnace Inside Flow）
// ======================================================

// ===== 基础初始化 =====
var view = graphView.getView();
var dm = graphView.dm();
graphView.setScrollBarVisible(false);

/**
 * ================================================================
 *  中棒加热炉出入炉 — 实时可视化监控系统
 * ================================================================
 * 
 * 【场景描述】
 *   单行轨道，一根固定长度 300 的钢坯从右至左运动，
 *   数据到达后直接解析位置并渲染，不做物理模拟。
 * 
 * 【架构概述】
 *   数据监听 → 头尾位置校正 → 直接渲染
 * 
 * 【外部依赖】
 *   - graphView   : HT for Web 图形视图实例（全局注入）
 *   - dataModel   : HT for Web 数据模型实例（全局注入）
 * ================================================================
 */

var view = graphView.getView();
var dm = graphView.dm();
graphView.setScrollBarVisible(false);

// ===== 双轨道纵坐标 =====
var rolly1 = dm.getDataByTag('roll-y1');
var rolly2 = dm.getDataByTag('roll-y2');

/**
 * 根据轨道索引获取 Y 坐标
 * @param {number} trackIndex - 轨道索引: 0→y1, 1→y2
 * @returns {number}
 */
function getYTrack(trackIndex) {
    if (trackIndex === 1) {
        return rolly2 ? rolly2.getPosition().y : 0;
    }
    return rolly1 ? rolly1.getPosition().y : 0;
}

// ===== 常量 =====
var MILL_TOTAL_LENGTH = 1500;
var STEEL_FIXED_LENGTH = 200;

// 属性与轨道的映射关系：监听到哪个属性，就用哪条轨道
var PROPERTY_TRACK_MAP = {
    'a:furnacetable': 0   // 属性名 → 轨道索引 (0→y1, 1→y2)
};

// ===== 热检坐标映射 =====
function getTrackPositionMap() {
    var map = {};
    dm.each(function (item) {
        var tag = item.getTag();
        if (tag && tag.startsWith('track-')) {
            var match = tag.match(/track-(\d+)-(.+)/);
            if (!match) return;
            map[match[2]] = Math.floor(MILL_TOTAL_LENGTH - item.getX());
        }
    });
    return map;
}
var TRACK_POSITION_MAP = getTrackPositionMap();
console.log('[加热炉] 热检坐标映射:', TRACK_POSITION_MAP);

// ===== 颜色映射 =====
var COLOR_MAP = {
    red: '#ff0000', green: '#00ff00', blue: '#0066ff', yellow: '#ffff00'
};

// ===== Shape 管理（双轨道） =====
// allSteelLines: slabNo → { shape, trackIndex }
var allSteelLines = {};

function createSteelLineShape(steel) {
    var line = new ht.Shape();
    line.setTag('steel-' + steel.slabNo);
    line.setStyle('label', steel.label);
    line.setStyle('shape.border.color', steel.borderColor);
    line.setStyle('label.position', "3");
    line.setStyle('label.font', "16px arial, sans-serif");
    line.setStyle('label.color', "rgb(255,255,255)");
    line.setStyle('shape.border.width', 6);
    line.setStyle('shape.type', 'polyline');
    line.setStyle('2d.movable', false);
    line.setStyle('shape.repeat.image', 'symbols/青岛特钢/扁钢钢坯.json');
    line.setLayer('0');
    line.setPoints([]);
    dm.add(line);
    return line;
}

function updateSteelLine(slabNo, headX, tailX) {
    var entry = allSteelLines[slabNo];
    if (!entry) return;
    var shape = entry.shape;
    var leftX = Math.min(headX, tailX);
    var rightX = Math.max(headX, tailX);
    var y = getYTrack(entry.trackIndex);
    var vs = Math.max(leftX, 0);
    var ve = Math.min(rightX, MILL_TOTAL_LENGTH);
    shape.setPoints(vs < ve ? [{ x: vs, y: y }, { x: ve, y: y }] : []);
}

function drawSteel(steel) {
    var slabNo = steel.slabNo;
    if (!allSteelLines[slabNo]) {
        var shape = createSteelLineShape(steel);
        allSteelLines[slabNo] = { shape: shape, trackIndex: steel.trackIndex || 0 };
    } else {
        var entry = allSteelLines[slabNo];
        entry.trackIndex = steel.trackIndex || 0;
        entry.shape.setStyle('label', steel.label);
        entry.shape.setStyle('shape.border.color', steel.borderColor);
    }
    updateSteelLine(slabNo, steel.headX, steel.tailX);
}

function renderSteels(steelList) {
    var activeSet = {};
    steelList.forEach(function (steel) {
        activeSet[steel.slabNo] = true;
        drawSteel(steel);
    });
    for (var slabNo in allSteelLines) {
        if (!activeSet[slabNo]) {
            dm.remove(allSteelLines[slabNo].shape);
            delete allSteelLines[slabNo];
        }
    }
}

// ================================================================
//  头尾位置校正函数
// ================================================================
function applyPositionCorrection(item) {
    var headX = item.headPosition ? TRACK_POSITION_MAP[item.headPosition] : undefined;
    var tailX = item.tailPosition ? TRACK_POSITION_MAP[item.tailPosition] : undefined;

    if (headX === undefined && tailX === undefined) return null;

    if (headX === undefined) headX = tailX - STEEL_FIXED_LENGTH;
    if (tailX === undefined) tailX = headX + STEEL_FIXED_LENGTH;

    var color = item.color || 'red';
    return {
        slabNo: item.slabNo,
        cardNo: item.cardNo,
        furnaceCode: item.furnaceCode || '',
        color: color,
        headX: headX,
        tailX: tailX,
        trackIndex: item._trackIndex || 0,
        label: item.furnaceCode ? item.cardNo + '-' + item.furnaceCode : (item.cardNo || ''),
        borderColor: COLOR_MAP[color] || '#ff0000'
    };
}

// ===== 全局炉内节点映射 =====
const positionMap = {
    A1: {},
    A2: {}
};

// ===== 表格缓存 =====
let inTable_A1 = [];
let inTable_A2 = [];
let outTable_A1 = [];
let outTable_A2 = [];


// ======================================================
// 🔥 节点缓存抽取层（核心复用点）
function cachePositionMap(furnaceKey, prefix) {
    const map = {};

    for (let i = 0; i <= 100; i++) {
        const tag = `${prefix}-${i}`;
        const node = dm.getDataByTag(tag);
        if (node) {
            map[i] = node;
        }
    }

    positionMap[furnaceKey] = map;
}


// ===== 炉内节点初始化 =====
cachePositionMap('A1', 'One');
cachePositionMap('A2', 'Two');


// ======================================================
// 🔥 will in / out 初始化（保持原逻辑）
for (var i = 1; i <= 10; i++) {
    let n = dm.getDataByTag('Onein-' + i);
    if (n) inTable_A1.push(n);
}

for (var i = 1; i <= 10; i++) {
    let n = dm.getDataByTag('Oneout-' + i);
    if (n) outTable_A1.push(n);
}

for (var i = 1; i <= 10; i++) {
    let n = dm.getDataByTag('Twoin-' + i);
    if (n) inTable_A2.push(n);
}

for (var i = 1; i <= 10; i++) {
    let n = dm.getDataByTag('Twoout-' + i);
    if (n) outTable_A2.push(n);
}


// ======================================================
// 🔥 炉内渲染层（加热炉炉内流核心）
function renderFurnaceInsideLayer(furnaceKey, dataList) {
    // ===== 数据兜底（关键）=====
    if (!dataList) {
        console.log('inside数据为空:', dataList);
        dataList = [];
    }

    if (!Array.isArray(dataList)) {
        console.log('inside数据不是数组:', dataList);
        dataList = dataList.data; // 兜底成数组
    }

    console.log('🔥 inside原始数据:', dataList);

    const occupied = new Set();

    dataList.forEach(item => {
        const pos = Number(item[0]);
        const RollPieceID = item[1];
        const info = item[2];
        const linecolor = item[3];

        const node = positionMap[furnaceKey]?.[pos];
        if (!node) return;

        occupied.add(pos);

        node.s('2d.visible', true);
        node.a('RollPieceID', RollPieceID);
        // ===== 原始信息保留 =====
        node.a('pos', pos)
        node.a('info', info);
        // 保留原始值
        node.a('linecolor', linecolor); 
        // 🔥 实际渲染颜色
        node.a('Color', mapColorToRGB(linecolor));
        node.a('furnace', furnaceKey);
    });

    Object.keys(positionMap[furnaceKey] || {}).forEach(pos => {
        if (!occupied.has(Number(pos))) {
            const node = positionMap[furnaceKey][pos];

            node.s('2d.visible', false);
            node.a('RollPieceID', '');
            node.a('info', '');
            node.a('linecolor', '');
            node.a('Color', 'rgb(0,0,0)');
        }
    });
}

// ===== 颜色映射 =====
function mapColorToRGB(color) {
    if (!color) return 'rgb(0,0,0)';

    const map = {
        red: 'rgb(255,0,0)',
        blue: 'rgb(51,153,255)',
        green: 'rgb(240,225,19)',
        yellow: 'rgb(255,255,0)',
        orange: 'rgb(255,165,0)'
    };

    return map[color.toLowerCase()] || 'rgb(0,0,0)';
}

// ======================================================
// 🔥 数据监听分发
dataModel.addDataPropertyChangeListener(function (e) {

    // ===== 炉内流渲染 =====
    if (e.property === 'a:A1-inside') {
        renderFurnaceInsideLayer('A1', e.newValue);
    }

    if (e.property === 'a:A2-inside') {
        renderFurnaceInsideLayer('A2', e.newValue);
    }

    // ===== 表格 =====
    if (e.property === 'a:A1-willin') updateTable(e.newValue, inTable_A1);
    if (e.property === 'a:A1-willout') updateTable(e.newValue, outTable_A1);

    if (e.property === 'a:A2-willin') updateTable(e.newValue, inTable_A2);
    if (e.property === 'a:A2-willout') updateTable(e.newValue, outTable_A2);

    if (e.property === 'a:A2-willout')
    {

    };
});


// ======================================================
// 🔥 节点点击绑定（统一入口）+ 右键菜单 100% 触发版
// ======================================================
Object.keys(positionMap).forEach(furnaceKey => {
    Object.values(positionMap[furnaceKey]).forEach(node => {

        // --- 左击事件（保留原有逻辑）---
        node.s('onClick', function (event) {
            event.stopPropagation();
            console.log('✅ 左击节点:', furnaceKey, node.a('RollPieceID'));
            
            // 存入上下文
            graphView._ctx = node;
            graphView._ctx.furnaceKey = furnaceKey;

            window.appBridge?.runNodeClickPlugins({
                node,
                event,
                furnaceKey
            });
        });

        // --- 👇 核心：HT 框架标准右键绑定（必触发）---
        node.s({
            // 开启右键响应
            'selectable': true,
            'focusable': true
        });

    });
});

// ======================================================
// 🔥 全局统一右键监听（最稳定，不会进不去）
// ======================================================
view.onContextMenu = function (event) {
    // 禁止浏览器原生右键
    event.preventDefault();
    event.stopPropagation();

    // 获取当前点击的节点
    const node = graphView.getDataAt(event);
    if (!node) {
        graphView._ctx = null;
        return;
    }

    // 判断是不是炉内节点（只在炉内节点显示菜单）
    const isFurnaceNode = Object.keys(positionMap).some(key => {
        return positionMap[key][node.a('pos')] === node;
    });
    if (!isFurnaceNode) return;

    // ✅ 存入上下文
    graphView._ctx = node;
    // 自动绑定炉号
    graphView._ctx.furnaceKey = node.a('furnace'); 
    
    console.log('✅ 右键触发节点:', node.a('RollPieceID'), '炉号:', node.a('furnace'));

    // 显示菜单
    contextmenu.show(event);
};


// ======================================================
// 🔥 点击空白关闭（已适配DOM弹窗体系）
view.addEventListener('click', function (e) {
    // 只有点击空白处才关闭
    if (!graphView.getDataAt(e)) {
        const popup = document.getElementById('steel-popup');
        if (popup) popup.remove();
        graphView._ctx = null;
    }
});


// ======================================================
// 🔥 右键菜单
const menuItems = [
    { label: "数据前移", action: () => handleMenuClick("forward") },
    { label: "数据后移", action: () => handleMenuClick("back") },
    { label: "查看计划", action: () => handleMenuClick("delete") },
    { label: "查看实绩", action: () => handleMenuClick("delete") },
    { label: "超温异常", action: () => handleMenuClick("delete") },
    { label: "超时异常", action: () => handleMenuClick("delete") },
    { label: "数据剔除", action: () => handleMenuClick("delete") },
];

const contextmenu = new ht.widget.ContextMenu(menuItems);

contextmenu.setVisibleFunc(() => {
    // 只要有 ctx 且有钢卷ID 就显示
    return graphView._ctx && graphView._ctx.a('RollPieceID');
});

contextmenu.addTo(view);


// ======================================================
// 🔥 菜单处理（ctx驱动）
function handleMenuClick(type) {

    const ctx = graphView._ctx;
    if (!ctx) return;
    const { furnaceKey, RollPieceID } = ctx;

    const line = furnaceKey === 'A2' ? "B202" : "B201";

    switch (type) {
        case "forward":
            requestForward(line, RollPieceID);
            break;
        case "back":
            requestBack(line, RollPieceID);
            break;
        case "delete":
            requestDelete(line, RollPieceID);
            break;
    }
}


// ======================================================
// 🔥 业务接口
function requestForward(line, slabNo) {
    requestGet("http://180.10.10.12:9003/api/sdf/sltbusfurtrack/singleforwardslab", {
        Line: line,
        SlabNo: slabNo
    });
}

function requestBack(line, slabNo) {
    requestGet("http://180.10.10.12:9003/api/sdf/sltbusfurtrack/singlebackwardslab", {
        Line: line,
        SlabNo: slabNo
    });
}

function requestDelete(line, slabNo) {
    requestGet("http://180.10.10.12:9003/api/sdf/sltbusfurtrack/delslab", {
        Line: line,
        SlabNo: slabNo
    });
}


// ======================================================
// 🔥 表格更新（原逻辑保留）
function updateTable(payload, table) {
    if (!payload || !table) return;

    const {
        data: d = {},
        msgTime,
        furnaceCode,
        eventCode
    } = payload;

    const fullData = {
        ...d,
        msgTime,
        furnaceCode,
        eventCode
    };

    const fieldOrder = [
        'cardNo',
        'sortNumber',
        'inMatNo',
        'steelGrade',
        'heatNo',
        'inMatThick',
        'inMatWidth',
        'inMatLen',
        'inMatWt',
        'rollPlanNo'
    ];

    fieldOrder.forEach((key, index) => {
        const node = table[index];
        if (node) node.a('ht.value', fullData[key] ?? '');
    });
}

let tableData1 ;
let tableData2 ;
// 1. 定义轮询控制器（安全核心：可中断、防重复）
let pollingTimer = null;
let isRequesting = false; // 防重复请求关键

// 2. 轮询核心函数
async function startPolling(interval = 3000) {
  // 防止多次调用 startPolling 导致多轮询同时运行
  if (pollingTimer) return;

  // 递归执行轮询
  const execute = async () => {
    try {
      // 防重复：上一个请求没结束，不发新请求
      if (isRequesting) return;
      isRequesting = true;

    // 👇 你的接口请求
    requestGet(`http://172.15.88.243:9003/api/bdy/bptbusrollingplan/getreadyplans?wholeBacklogCode=B1&furNo=A1`)
    .then(data => {
        tableData1 = data.Data;
        let table1 = graphView.dm().getDataByTag('1#plan');
        table1.a('ht.dataSource',tableData1);
        console.log(tableData1);
    });

    requestGet(`http://172.15.88.243:9003/api/bdy/bptbusrollingplan/getreadyplans?wholeBacklogCode=B1&furNo=A2`)
    .then(data => {
        tableData2 = data.Data;
        let table2 = graphView.dm().getDataByTag('2#plan');
        table2.a('ht.dataSource',tableData2);
        console.log(tableData2);
    });

    } catch (err) {
      console.error("轮询异常：", err);
      // 安全：出错后不中断轮询，继续执行
    } finally {
      isRequesting = false; // 重置请求状态
      // 上一次请求结束后，再延迟指定时间发起下一次（绝对不堆积）
      pollingTimer = setTimeout(execute, interval);
    };
  };

  // 启动第一次
  execute();
}

// 3. 安全停止轮询（必须！防止内存泄漏）
function stopPolling() {
  if (pollingTimer) {
    clearTimeout(pollingTimer);
    pollingTimer = null;
  }
  isRequesting = false;
}

// ============= 使用方式 =============
startPolling(5000); // 每3秒轮询一次
// stopPolling(); // 页面销毁/切换时必须调用}

